CREATE TABLE IF NOT EXISTS public.payment_intents (id uuid primary key default gen_random_uuid(),provider_transaction_id text not null unique,provider_subscription_id text,email text not null,amount_mur numeric not null check(amount_mur>0),currency text not null default 'MUR',covers_fees boolean not null default false,source_initiative_id uuid references public.initiatives(id) on delete set null,is_test boolean not null default false,status text not null default 'pending' check(status in ('pending','completed','failed','expired')),created_at timestamptz not null default now(),completed_at timestamptz);
ALTER TABLE public.payment_intents ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.payment_intents FROM anon,authenticated;
GRANT SELECT ON public.payment_intents TO authenticated;
CREATE OR REPLACE FUNCTION public.create_test_payment_intent(p_email text,p_amount_mur numeric,p_covers_fees boolean default false,p_source_initiative_id uuid default null,p_provider_subscription_id text default null) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_txn text:='mock_txn_'||replace(gen_random_uuid()::text,'-',''); BEGIN IF p_email IS NULL OR btrim(p_email)='' OR p_amount_mur IS NULL OR p_amount_mur<=0 THEN RAISE EXCEPTION 'Invalid test payment intent'; END IF; INSERT INTO public.payment_intents(provider_transaction_id,provider_subscription_id,email,amount_mur,covers_fees,source_initiative_id,is_test) VALUES(v_txn,p_provider_subscription_id,lower(btrim(p_email)),p_amount_mur,coalesce(p_covers_fees,false),p_source_initiative_id,true); RETURN v_txn; END; $$;
REVOKE ALL ON FUNCTION public.create_test_payment_intent(text,numeric,boolean,uuid,text) FROM public;
GRANT EXECUTE ON FUNCTION public.create_test_payment_intent(text,numeric,boolean,uuid,text) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.finalize_test_signup_payment(p_user_id uuid,p_email text,p_transaction_id text,p_provider_subscription_id text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_intent public.payment_intents%rowtype; v_payment_id uuid; v_subscription_id uuid; BEGIN SELECT * INTO v_intent FROM public.payment_intents WHERE provider_transaction_id=p_transaction_id AND status='pending' AND is_test=true AND lower(email)=lower(p_email) FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Valid pending test payment intent not found'; END IF; INSERT INTO public.payments(user_id,amount_mur,status,peach_payment_id,paid_at,currency,processor_response,fees_covered_amount_mur,reconciliation_status,is_test) VALUES(p_user_id,v_intent.amount_mur,'pending',v_intent.provider_transaction_id,null,v_intent.currency,jsonb_build_object('simulated',true,'payment_intent_id',v_intent.id),0,'pending',true) ON CONFLICT(peach_payment_id) WHERE peach_payment_id IS NOT NULL DO NOTHING RETURNING id INTO v_payment_id; IF v_payment_id IS NULL THEN SELECT id INTO v_payment_id FROM public.payments WHERE peach_payment_id=v_intent.provider_transaction_id LIMIT 1; END IF; PERFORM public.allocate_payment_funds(v_payment_id,p_user_id,v_intent.amount_mur); UPDATE public.payments SET status='success',paid_at=now(),reconciliation_status='success',gateway_response=jsonb_build_object('simulated',true,'payment_intent_id',v_intent.id,'provider_subscription_id',p_provider_subscription_id) WHERE id=v_payment_id; SELECT id INTO v_subscription_id FROM public.subscriptions WHERE user_id=p_user_id ORDER BY created_at DESC LIMIT 1; IF v_subscription_id IS NULL THEN INSERT INTO public.subscriptions(user_id,amount_mur,status,peach_subscription_id,covers_fees,start_date,next_billing_date) VALUES(p_user_id,v_intent.amount_mur,'active',p_provider_subscription_id,v_intent.covers_fees,now(),now()+interval '1 month') RETURNING id INTO v_subscription_id; ELSE UPDATE public.subscriptions SET status='active',amount_mur=v_intent.amount_mur,peach_subscription_id=coalesce(p_provider_subscription_id,peach_subscription_id),covers_fees=v_intent.covers_fees,start_date=coalesce(start_date,now()),next_billing_date=now()+interval '1 month',updated_at=now() WHERE id=v_subscription_id; END IF; UPDATE public.payments SET subscription_id=v_subscription_id WHERE id=v_payment_id; UPDATE public.payment_intents SET status='completed',completed_at=now(),provider_subscription_id=p_provider_subscription_id WHERE id=v_intent.id; RETURN v_payment_id; END; $$;
REVOKE ALL ON FUNCTION public.finalize_test_signup_payment(uuid,text,text,text) FROM public,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.finalize_test_signup_payment(uuid,text,text,text) TO postgres;
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sub_amount numeric; fee_cover boolean; v_payment_id uuid; v_payment_txn text; v_provider_sub text; BEGIN INSERT INTO public.profiles(id,full_name,email) VALUES(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),new.email) ON CONFLICT(id) DO UPDATE SET full_name=excluded.full_name,email=excluded.email; INSERT INTO public.user_roles(user_id,role) VALUES(new.id,'member') ON CONFLICT(user_id,role) DO NOTHING; sub_amount:=(new.raw_user_meta_data->>'subscription_amount')::numeric; fee_cover:=coalesce((new.raw_user_meta_data->>'covers_fees')::boolean,false); v_payment_txn:=new.raw_user_meta_data->>'payment_transaction_id'; v_provider_sub:=new.raw_user_meta_data->>'provider_subscription_id'; IF sub_amount IS NOT NULL AND sub_amount>0 THEN IF v_payment_txn IS NOT NULL AND v_payment_txn<>'' THEN v_payment_id:=public.finalize_test_signup_payment(new.id,new.email,v_payment_txn,v_provider_sub); ELSE INSERT INTO public.subscriptions(user_id,amount_mur,status,covers_fees) VALUES(new.id,sub_amount,'pending',fee_cover); END IF; END IF; RETURN new; END; $$;